import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';

const ROOT = process.cwd();
const must = (ok, message) => { if (!ok) throw new Error(message); };
const read = p => fs.readFileSync(path.join(ROOT, p), 'utf8');
const write = (p, content) => {
  const file = path.join(ROOT, p);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content, 'utf8');
  console.log('WRITE', p);
};
const backup = p => {
  const src = path.join(ROOT, p);
  const dst = src + '.pre-line-tracking.bak';
  if (!fs.existsSync(dst)) fs.copyFileSync(src, dst);
};
const replaceOnce = (text, from, to, label) => {
  if (text.includes(to)) return text;
  must(text.includes(from), `Patch marker not found: ${label}`);
  return text.replace(from, to);
};

const required = [
  'api/diagnostics.js',
  'server.mjs',
  'vercel.json',
  'public/index.html',
  'scripts-check.mjs',
  'package.json'
];
for (const p of required) must(fs.existsSync(path.join(ROOT, p)), `Missing ${p}. Run this from Live-view repo root.`);

const newFiles = {
  "LINE-TRACKING-SETUP-TH.md": "# LINE Tracking for Live-view\n\nแพตช์นี้เพิ่มหน้า `/line-tracking` และ Windows Agent สำหรับจับเลขพัสดุจาก LINE Chrome Extension\n\n## วิธีใช้แพตช์\n\nวาง `APPLY-LINE-TRACKING.mjs` ที่ root ของ repo `Live-view` แล้วรัน:\n\n```bat\nnode APPLY-LINE-TRACKING.mjs\n```\n\nสคริปต์จะ:\n- backup ไฟล์เดิมเป็น `*.pre-line-tracking.bak`\n- เพิ่มหน้า `/line-tracking`\n- เพิ่ม API ผ่าน `/api/diagnostics` เดิม เพื่อคง Vercel Hobby ไว้ที่ 12 Functions\n- เพิ่ม Vercel Private Blob state\n- เพิ่ม `line-agent/`\n- รัน `npm test`\n\nหลัง PASS:\n\n```bat\ngit add .\ngit commit -m \"Add LINE parcel tracking agent\"\ngit push\n```\n\nจากนั้นตั้ง `LINE_AGENT_SECRET` ใน Vercel และติดตั้ง Agent ตาม `line-agent/README-TH.md`\n",
  "lib/line-tracking.mjs": "import crypto from 'node:crypto';\nimport { isAuthed } from './core.mjs';\nimport { SECURITY_HEADERS } from './security.mjs';\n\nconst STATE_PATH = String(process.env.LINE_TRACKING_BLOB_PATH || 'pancake-live/line-tracking-state.json').trim();\nconst RETENTION_MS = 45 * 24 * 60 * 60 * 1000;\nconst OVERDUE_MS = 2 * 24 * 60 * 60 * 1000;\nconst ONLINE_MS = 90 * 1000;\nconst TRACKING_RE = /^TH[A-Z0-9]{8,20}$/;\n\nfunction production() {\n  return !!process.env.VERCEL || process.env.NODE_ENV === 'production';\n}\n\nfunction json(status, body, headers = {}) {\n  return {\n    status,\n    headers: {\n      ...SECURITY_HEADERS,\n      'content-type': 'application/json; charset=utf-8',\n      'cache-control': 'private, no-store, max-age=0',\n      pragma: 'no-cache',\n      ...headers\n    },\n    body: JSON.stringify(body)\n  };\n}\n\nfunction emptyState() {\n  return {\n    v: 1,\n    updatedAt: new Date(0).toISOString(),\n    agent: { id: '', version: '', lastSeenAt: null, lineConnected: false },\n    requests: [],\n    unmatched: []\n  };\n}\n\nfunction text(value, max = 160) {\n  return String(value || '').trim().slice(0, max);\n}\n\nfunction iso(value, fallback = Date.now()) {\n  const raw = typeof value === 'number' ? value : Date.parse(String(value || ''));\n  const ms = Number.isFinite(raw) ? raw : fallback;\n  return new Date(ms).toISOString();\n}\n\nfunction safeId(value, fallback = '') {\n  const v = text(value, 180);\n  return /^[A-Za-z0-9._:-]{6,180}$/.test(v) ? v : fallback;\n}\n\nfunction safeTracking(value) {\n  const v = text(value, 40).toUpperCase();\n  return TRACKING_RE.test(v) ? v : '';\n}\n\nfunction bearer(headers = {}) {\n  const raw = String(headers.authorization || headers.Authorization || '');\n  const m = raw.match(/^Bearer\\s+(.+)$/i);\n  return m ? m[1].trim() : '';\n}\n\nfunction constantTimeEqual(a, b) {\n  const aa = Buffer.from(String(a || ''), 'utf8');\n  const bb = Buffer.from(String(b || ''), 'utf8');\n  return aa.length === bb.length && aa.length > 0 && crypto.timingSafeEqual(aa, bb);\n}\n\nexport function lineAgentConfigured() {\n  return !!String(process.env.LINE_AGENT_SECRET || '').trim();\n}\n\nexport function isLineAgentAuthorized(headers = {}) {\n  const expected = String(process.env.LINE_AGENT_SECRET || (production() ? '' : 'line-agent-local-dev')).trim();\n  return !!expected && constantTimeEqual(bearer(headers), expected);\n}\n\nasync function blobSdk() {\n  if (globalThis.__lineTrackingBlobSdk) return globalThis.__lineTrackingBlobSdk;\n  return import('@vercel/blob');\n}\n\nfunction localMemoryEnabled() {\n  return !production()\n    && !process.env.BLOB_READ_WRITE_TOKEN\n    && !process.env.BLOB_STORE_ID\n    && !process.env.VERCEL_OIDC_TOKEN;\n}\n\nasync function loadState() {\n  if (localMemoryEnabled()) {\n    const state = globalThis.__lineTrackingMemoryState || (globalThis.__lineTrackingMemoryState = emptyState());\n    return { state: structuredClone(state), etag: null, memory: true };\n  }\n\n  const { get } = await blobSdk();\n  const result = await get(STATE_PATH, { access: 'private', useCache: false });\n  if (!result?.stream) return { state: emptyState(), etag: null, memory: false };\n\n  const raw = await new Response(result.stream).text();\n  if (!raw.trim()) return { state: emptyState(), etag: result.blob?.etag || null, memory: false };\n\n  let state;\n  try { state = JSON.parse(raw); }\n  catch { throw new Error('LINE tracking state is not valid JSON'); }\n\n  if (!state || typeof state !== 'object') state = emptyState();\n  if (!Array.isArray(state.requests)) state.requests = [];\n  if (!Array.isArray(state.unmatched)) state.unmatched = [];\n  if (!state.agent || typeof state.agent !== 'object') state.agent = emptyState().agent;\n\n  return { state, etag: result.blob?.etag || null, memory: false };\n}\n\nasync function saveState(state, etag, memory) {\n  state.updatedAt = new Date().toISOString();\n\n  if (memory) {\n    globalThis.__lineTrackingMemoryState = structuredClone(state);\n    return;\n  }\n\n  const { put } = await blobSdk();\n  await put(STATE_PATH, JSON.stringify(state), {\n    access: 'private',\n    addRandomSuffix: false,\n    allowOverwrite: !!etag,\n    ...(etag ? { ifMatch: etag } : {}),\n    contentType: 'application/json; charset=utf-8',\n    cacheControlMaxAge: 60\n  });\n}\n\nfunction normalizeEvent(raw = {}) {\n  const type = text(raw.type, 24).toLowerCase();\n  const eventId = safeId(raw.eventId, crypto.randomUUID());\n  const occurredAt = iso(raw.occurredAt);\n\n  if (type === 'heartbeat') {\n    return {\n      type,\n      eventId,\n      occurredAt,\n      agentId: safeId(raw.agentId, 'line-agent'),\n      agentVersion: text(raw.agentVersion, 40),\n      lineConnected: raw.lineConnected === true\n    };\n  }\n\n  if (type === 'request') {\n    const requestId = safeId(raw.requestId);\n    if (!requestId) return null;\n    return { type, eventId, occurredAt, requestId };\n  }\n\n  if (type === 'tracking') {\n    const tracking = safeTracking(raw.tracking);\n    if (!tracking) return null;\n    return {\n      type,\n      eventId,\n      occurredAt,\n      tracking,\n      requestId: safeId(raw.requestId),\n      recovered: raw.recovered === true\n    };\n  }\n\n  return null;\n}\n\nfunction cleanup(state, now = Date.now()) {\n  state.requests = state.requests.filter(row => {\n    const anchor = Date.parse(row.receivedAt || row.requestedAt || 0);\n    return Number.isFinite(anchor) && now - anchor <= RETENTION_MS;\n  }).slice(-5000);\n\n  state.unmatched = state.unmatched.filter(row => {\n    const anchor = Date.parse(row.receivedAt || 0);\n    return Number.isFinite(anchor) && now - anchor <= RETENTION_MS;\n  }).slice(-2000);\n}\n\nfunction applyEvent(state, event) {\n  if (event.type === 'heartbeat') {\n    state.agent = {\n      id: event.agentId,\n      version: event.agentVersion,\n      lastSeenAt: event.occurredAt,\n      lineConnected: event.lineConnected\n    };\n    return;\n  }\n\n  if (event.type === 'request') {\n    const found = state.requests.find(x => x.id === event.requestId);\n    if (!found) {\n      state.requests.push({\n        id: event.requestId,\n        requestedAt: event.occurredAt,\n        receivedAt: null,\n        tracking: null,\n        recovered: false\n      });\n    }\n    return;\n  }\n\n  if (event.type === 'tracking') {\n    const existingTracking = state.requests.find(x => x.tracking === event.tracking);\n    if (existingTracking) return;\n    if (state.unmatched.some(x => x.tracking === event.tracking)) return;\n\n    if (event.requestId) {\n      let request = state.requests.find(x => x.id === event.requestId);\n      if (!request) {\n        request = {\n          id: event.requestId,\n          requestedAt: null,\n          receivedAt: null,\n          tracking: null,\n          recovered: true\n        };\n        state.requests.push(request);\n      }\n\n      request.tracking = event.tracking;\n      request.receivedAt = event.occurredAt;\n      request.recovered = !!event.recovered || request.recovered;\n      return;\n    }\n\n    state.unmatched.push({\n      id: event.eventId,\n      tracking: event.tracking,\n      receivedAt: event.occurredAt\n    });\n  }\n}\n\nfunction isConflict(error) {\n  const name = String(error?.name || '');\n  const message = String(error?.message || error || '');\n  return /Precondition/i.test(name) || /precondition|etag|412|409|already exists|conflict/i.test(message);\n}\n\nexport async function ingestLineEvents(rawEvents) {\n  const incoming = (Array.isArray(rawEvents) ? rawEvents : [rawEvents])\n    .slice(0, 100)\n    .map(normalizeEvent)\n    .filter(Boolean);\n\n  if (!incoming.length) return { ok: true, accepted: 0 };\n\n  let lastError;\n  for (let attempt = 0; attempt < 4; attempt++) {\n    const loaded = await loadState();\n    const state = loaded.state;\n\n    for (const event of incoming) applyEvent(state, event);\n    cleanup(state);\n\n    try {\n      await saveState(state, loaded.etag, loaded.memory);\n      return { ok: true, accepted: incoming.length, updatedAt: state.updatedAt };\n    } catch (error) {\n      lastError = error;\n      if (!isConflict(error) || attempt === 3) throw error;\n      await new Promise(resolve => setTimeout(resolve, 40 + attempt * 60));\n    }\n  }\n\n  throw lastError || new Error('Unable to update LINE tracking state');\n}\n\nfunction bangkokDay(value) {\n  const ms = Date.parse(value || '');\n  if (!Number.isFinite(ms)) return '';\n  return new Date(ms + 7 * 60 * 60 * 1000).toISOString().slice(0, 10);\n}\n\nfunction statusFor(row, now) {\n  if (row.receivedAt && row.tracking) return 'RECEIVED';\n  const requestedAt = Date.parse(row.requestedAt || '');\n  if (Number.isFinite(requestedAt) && now - requestedAt >= OVERDUE_MS) return 'OVERDUE';\n  return 'WAITING';\n}\n\nexport async function lineTrackingSnapshot({ limit = 400 } = {}) {\n  const { state } = await loadState();\n  cleanup(state);\n\n  const now = Date.now();\n  const today = bangkokDay(new Date(now).toISOString());\n  const rows = state.requests.map(row => ({\n    id: row.id,\n    status: statusFor(row, now),\n    requestedAt: row.requestedAt || null,\n    receivedAt: row.receivedAt || null,\n    tracking: row.tracking || null,\n    recovered: !!row.recovered\n  }));\n\n  const unmatched = state.unmatched.map(row => ({\n    id: row.id,\n    status: 'UNMATCHED',\n    requestedAt: null,\n    receivedAt: row.receivedAt || null,\n    tracking: row.tracking || null,\n    recovered: false\n  }));\n\n  const all = [...rows, ...unmatched];\n  const rank = { OVERDUE: 0, WAITING: 1, UNMATCHED: 2, RECEIVED: 3 };\n  all.sort((a, b) => {\n    const ra = rank[a.status] ?? 9;\n    const rb = rank[b.status] ?? 9;\n    if (ra !== rb) return ra - rb;\n    const ta = Date.parse(a.receivedAt || a.requestedAt || 0) || 0;\n    const tb = Date.parse(b.receivedAt || b.requestedAt || 0) || 0;\n    return tb - ta;\n  });\n\n  const lastSeenMs = Date.parse(state.agent?.lastSeenAt || '');\n  const agentOnline = Number.isFinite(lastSeenMs) && now - lastSeenMs <= ONLINE_MS;\n\n  return {\n    ok: true,\n    storage: localMemoryEnabled() ? 'memory-dev' : 'vercel-private-blob',\n    updatedAt: state.updatedAt,\n    agent: {\n      online: agentOnline,\n      lineConnected: agentOnline && state.agent?.lineConnected === true,\n      id: state.agent?.id || '',\n      version: state.agent?.version || '',\n      lastSeenAt: state.agent?.lastSeenAt || null\n    },\n    counts: {\n      waiting: rows.filter(x => x.status === 'WAITING').length,\n      overdue: rows.filter(x => x.status === 'OVERDUE').length,\n      receivedToday: rows.filter(x => x.status === 'RECEIVED' && bangkokDay(x.receivedAt) === today).length,\n      unmatched: unmatched.length,\n      total: all.length\n    },\n    items: all.slice(0, Math.max(1, Math.min(1000, Number(limit) || 400)))\n  };\n}\n\nexport async function lineTrackingRoute({ method = 'GET', headers = {}, body = {}, query = {} } = {}) {\n  const verb = String(method || 'GET').toUpperCase();\n\n  if (verb === 'GET') {\n    if (!isAuthed(headers)) return json(401, { ok: false, error: 'Unauthorized' });\n    try {\n      return json(200, await lineTrackingSnapshot({ limit: query.limit }));\n    } catch (error) {\n      return json(503, {\n        ok: false,\n        error: 'LINE tracking storage is unavailable',\n        detail: String(error?.message || error || '')\n      });\n    }\n  }\n\n  if (verb === 'POST') {\n    if (production() && !lineAgentConfigured()) {\n      return json(503, { ok: false, error: 'LINE_AGENT_SECRET is not configured' });\n    }\n    if (!isLineAgentAuthorized(headers)) {\n      return json(401, { ok: false, error: 'Unauthorized agent' });\n    }\n\n    try {\n      const events = Array.isArray(body?.events) ? body.events : body;\n      return json(200, await ingestLineEvents(events));\n    } catch (error) {\n      return json(503, {\n        ok: false,\n        error: 'Unable to save LINE tracking events',\n        detail: String(error?.message || error || '')\n      });\n    }\n  }\n\n  return json(405, { ok: false, error: 'Method Not Allowed' }, { allow: 'GET, POST' });\n}\n",
  "public/line-tracking.html": "<!doctype html>\n<html lang=\"th\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#080a10\">\n  <title>LINE Tracking · Pancake Live</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Thai:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"/style.css\">\n  <link rel=\"stylesheet\" href=\"/line-tracking.css\">\n</head>\n<body class=\"line-track-page\">\n  <div class=\"line-track-bg\" aria-hidden=\"true\"><i></i><i></i><i></i></div>\n\n  <nav class=\"line-track-nav liquid-pill\">\n    <a class=\"line-track-brand\" href=\"/\" aria-label=\"กลับหน้าหลัก\">\n      <i></i><span>LINE TRACKING</span>\n    </a>\n    <div class=\"line-track-nav-actions\">\n      <a class=\"icon-btn\" href=\"/\" title=\"ยอดขาย\" aria-label=\"ยอดขาย\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 19V9M10 19V5M16 19v-7M22 19V3\"/></svg>\n      </a>\n      <a class=\"icon-btn\" href=\"/settings\" title=\"ตั้งค่า\" aria-label=\"ตั้งค่า\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 15.2a3.2 3.2 0 1 0 0-6.4 3.2 3.2 0 0 0 0 6.4Z\"/><path d=\"M19.4 13.5c.1-.5.1-1 0-1.5l1.7-1.3-2-3.4-2 .8a7.3 7.3 0 0 0-1.3-.8L15.5 5h-4l-.3 2.3c-.5.2-.9.5-1.3.8l-2-.8-2 3.4L7.6 12a8 8 0 0 0 0 1.5l-1.7 1.3 2 3.4 2-.8c.4.3.8.6 1.3.8l.3 2.3h4l.3-2.3c.5-.2.9-.5 1.3-.8l2 .8 2-3.4-1.7-1.3Z\"/></svg>\n      </a>\n      <button id=\"lineLogoutBtn\" class=\"icon-btn\" title=\"ออกจากระบบ\" aria-label=\"ออกจากระบบ\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M10 5H6a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h4M14 8l4 4-4 4M18 12H9\"/></svg>\n      </button>\n    </div>\n  </nav>\n\n  <main class=\"line-track-shell\">\n    <header class=\"line-track-head\">\n      <div>\n        <div class=\"micro-label\">AUTOMATIC REPLY TRACKER</div>\n        <h1>เลขพัสดุจาก LINE</h1>\n        <p>จับเฉพาะงานที่ส่งขอเลข และ Reply ที่มีเลขพัสดุ โดยไม่เก็บชื่อหรือข้อมูลลูกค้าบนเว็บ</p>\n      </div>\n      <div id=\"agentBadge\" class=\"line-agent-badge offline\"><i></i><span>AGENT OFFLINE</span></div>\n    </header>\n\n    <section class=\"line-stats\" aria-label=\"สรุปสถานะ\">\n      <article><span>รอเลข</span><strong id=\"waitingCount\">0</strong><small>ภายใน 2 วัน</small></article>\n      <article><span>เกินกำหนด</span><strong id=\"overdueCount\">0</strong><small>รอเกิน 2 วัน</small></article>\n      <article><span>ได้วันนี้</span><strong id=\"receivedCount\">0</strong><small>Reply สำเร็จ</small></article>\n      <article><span>จับคู่ไม่ได้</span><strong id=\"unmatchedCount\">0</strong><small>ตรวจสอบเอง</small></article>\n    </section>\n\n    <section class=\"line-track-card liquid-glass\">\n      <div class=\"line-toolbar\">\n        <label class=\"line-search\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"6\"/><path d=\"m16 16 4 4\"/></svg>\n          <input id=\"trackingSearch\" type=\"search\" autocomplete=\"off\" placeholder=\"ค้นหาเลขพัสดุ...\">\n        </label>\n        <div id=\"filterBar\" class=\"line-filters\">\n          <button class=\"active\" data-filter=\"all\">ทั้งหมด</button>\n          <button data-filter=\"waiting\">รอเลข</button>\n          <button data-filter=\"overdue\">เกิน 2 วัน</button>\n          <button data-filter=\"received\">ได้เลขแล้ว</button>\n          <button data-filter=\"unmatched\">จับคู่ไม่ได้</button>\n        </div>\n      </div>\n\n      <div class=\"line-track-meta\">\n        <span id=\"lastSync\">กำลังเชื่อมต่อ...</span>\n        <span id=\"lineConnection\">LINE —</span>\n      </div>\n\n      <div id=\"trackingError\" class=\"line-track-error hidden\"></div>\n      <div id=\"trackingList\" class=\"tracking-list\">\n        <div class=\"line-empty\">กำลังโหลดข้อมูล…</div>\n      </div>\n    </section>\n  </main>\n\n  <script src=\"/security.js\"></script>\n  <script src=\"/line-tracking.js\" type=\"module\"></script>\n</body>\n</html>\n",
  "public/line-tracking.css": ":root{--line-green:#7ff5be;--line-yellow:#ffd178;--line-red:#ff8297;--line-blue:#9bc7ff}\n.line-track-page{min-height:100vh;overflow:auto;background:#070910;color:#f7f8fb;padding:96px 18px 44px}\n.line-track-bg{position:fixed;inset:0;overflow:hidden;pointer-events:none;background:radial-gradient(circle at 18% 5%,rgba(91,239,164,.12),transparent 34%),radial-gradient(circle at 88% 10%,rgba(132,122,255,.13),transparent 33%),linear-gradient(160deg,#070910,#0b0f19 55%,#080b12)}\n.line-track-bg i{position:absolute;border-radius:50%;filter:blur(70px);opacity:.24}.line-track-bg i:nth-child(1){width:340px;height:340px;left:-80px;top:15%;background:#0fd67b}.line-track-bg i:nth-child(2){width:420px;height:420px;right:-150px;top:30%;background:#655dff}.line-track-bg i:nth-child(3){width:260px;height:260px;left:42%;bottom:-120px;background:#187dff}\n.line-track-nav{position:fixed;z-index:20;left:50%;top:18px;transform:translateX(-50%);width:min(1180px,calc(100vw - 34px));height:56px;padding:7px 8px 7px 16px;border:1px solid rgba(255,255,255,.13);border-radius:24px;background:rgba(10,13,22,.66);backdrop-filter:blur(28px) saturate(150%);display:flex;align-items:center;justify-content:space-between;box-shadow:0 16px 46px rgba(0,0,0,.28)}\n.line-track-brand{display:flex;align-items:center;gap:10px;text-decoration:none;font:750 10px/1 \"Manrope\",\"IBM Plex Sans Thai\",sans-serif;letter-spacing:.16em}.line-track-brand i{width:8px;height:8px;border-radius:50%;background:var(--line-green);box-shadow:0 0 18px rgba(127,245,190,.7)}\n.line-track-nav-actions{display:flex;gap:3px}\n.line-track-shell{position:relative;z-index:2;width:min(1180px,100%);margin:0 auto}\n.line-track-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin:8px 6px 22px}.line-track-head h1{font:800 clamp(28px,4vw,48px)/1.05 \"Manrope\",\"IBM Plex Sans Thai\",sans-serif;letter-spacing:-.045em;margin:7px 0 8px}.line-track-head p{margin:0;max-width:720px;color:rgba(238,241,248,.52);font-size:12px;line-height:1.7}.line-agent-badge{height:38px;padding:0 14px;display:flex;align-items:center;gap:8px;border-radius:999px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.04);font:750 8px/1 \"Manrope\",sans-serif;letter-spacing:.12em;white-space:nowrap}.line-agent-badge i{width:7px;height:7px;border-radius:50%;background:currentColor;box-shadow:0 0 13px currentColor}.line-agent-badge.online{color:var(--line-green)}.line-agent-badge.offline{color:var(--line-red)}.line-agent-badge.partial{color:var(--line-yellow)}\n.line-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px}.line-stats article{min-height:112px;padding:17px 18px;border-radius:23px;border:1px solid rgba(255,255,255,.085);background:linear-gradient(145deg,rgba(255,255,255,.06),rgba(255,255,255,.018));backdrop-filter:blur(18px);display:grid;align-content:end}.line-stats span{font-size:10px;color:rgba(238,241,248,.48)}.line-stats strong{font:800 36px/1.05 \"Manrope\",sans-serif;letter-spacing:-.045em;margin:7px 0 2px}.line-stats small{font-size:8px;color:rgba(238,241,248,.28)}\n.line-track-card{border-radius:30px;border:1px solid rgba(255,255,255,.11);background:linear-gradient(145deg,rgba(13,17,27,.72),rgba(10,13,21,.45));backdrop-filter:blur(22px) saturate(120%);padding:16px;min-height:430px}\n.line-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px}.line-search{height:43px;min-width:260px;flex:1;max-width:440px;display:flex;align-items:center;gap:9px;padding:0 13px;border-radius:15px;border:1px solid rgba(255,255,255,.085);background:rgba(255,255,255,.035)}.line-search svg{width:17px;height:17px;fill:none;stroke:rgba(238,241,248,.45);stroke-width:1.7}.line-search input{width:100%;border:0;outline:0;background:transparent;color:#f7f8fb;font-size:11px}.line-search input::placeholder{color:rgba(238,241,248,.28)}\n.line-filters{display:flex;gap:5px;overflow:auto;padding:2px}.line-filters button{border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.025);color:rgba(238,241,248,.48);border-radius:12px;min-height:38px;padding:0 12px;white-space:nowrap;cursor:pointer;font-size:9px}.line-filters button:hover{background:rgba(255,255,255,.06)}.line-filters button.active{background:rgba(127,245,190,.10);border-color:rgba(127,245,190,.2);color:#a8f8d1}\n.line-track-meta{margin:13px 3px 10px;display:flex;justify-content:space-between;gap:12px;color:rgba(238,241,248,.3);font-size:8px;letter-spacing:.04em}\n.tracking-list{display:grid;gap:8px}.tracking-row{display:grid;grid-template-columns:108px minmax(0,1fr) auto;gap:14px;align-items:center;min-height:78px;padding:12px 13px;border-radius:18px;border:1px solid rgba(255,255,255,.065);background:rgba(255,255,255,.025)}.tracking-row:hover{background:rgba(255,255,255,.045)}.tracking-state{display:flex;align-items:center;gap:7px;font-size:9px;font-weight:700}.tracking-state i{width:7px;height:7px;border-radius:50%;background:currentColor;box-shadow:0 0 12px currentColor}.tracking-row.waiting .tracking-state{color:var(--line-yellow)}.tracking-row.overdue .tracking-state{color:var(--line-red)}.tracking-row.received .tracking-state{color:var(--line-green)}.tracking-row.unmatched .tracking-state{color:var(--line-blue)}\n.tracking-main{min-width:0}.tracking-number{font:780 15px/1.2 \"Manrope\",sans-serif;letter-spacing:.025em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.tracking-number.muted{font-size:11px;color:rgba(238,241,248,.42);letter-spacing:0}.tracking-sub{margin-top:5px;display:flex;gap:10px;flex-wrap:wrap;color:rgba(238,241,248,.32);font-size:8px}.tracking-sub b{color:rgba(238,241,248,.52);font-weight:620}.copy-track{height:36px;padding:0 12px;border-radius:12px;border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.035);color:rgba(247,248,251,.76);cursor:pointer;font-size:9px}.copy-track:hover{background:rgba(127,245,190,.08);border-color:rgba(127,245,190,.18);color:#b8f9d9}.copy-track:disabled{opacity:.28;cursor:default}\n.line-empty{padding:70px 15px;text-align:center;color:rgba(238,241,248,.33);font-size:11px}.line-track-error{margin:10px 0;padding:12px 14px;border-radius:15px;background:rgba(255,86,111,.08);border:1px solid rgba(255,105,126,.16);color:#ff9aaa;font-size:10px}\n@media(max-width:820px){.line-track-page{padding:88px 10px 28px}.line-track-head{align-items:flex-start;flex-direction:column}.line-stats{grid-template-columns:repeat(2,1fr)}.line-toolbar{align-items:stretch;flex-direction:column}.line-search{max-width:none;min-width:0}.tracking-row{grid-template-columns:94px minmax(0,1fr) auto}}\n@media(max-width:540px){.line-track-nav{width:calc(100vw - 18px);top:9px}.line-track-page{padding-top:78px}.line-stats{gap:7px}.line-stats article{min-height:94px;padding:13px}.line-stats strong{font-size:29px}.tracking-row{grid-template-columns:1fr auto;gap:8px}.tracking-state{grid-column:1/-1}.tracking-number{font-size:13px}.line-track-meta{align-items:flex-start;flex-direction:column}}\n",
  "public/line-tracking.js": "const $ = id => document.getElementById(id);\n\nconst els = {\n  agent: $('agentBadge'),\n  waiting: $('waitingCount'),\n  overdue: $('overdueCount'),\n  received: $('receivedCount'),\n  unmatched: $('unmatchedCount'),\n  search: $('trackingSearch'),\n  filterBar: $('filterBar'),\n  list: $('trackingList'),\n  error: $('trackingError'),\n  sync: $('lastSync'),\n  lineConnection: $('lineConnection'),\n  logout: $('lineLogoutBtn')\n};\n\nlet snapshot = { items: [], counts: {}, agent: {} };\nlet activeFilter = 'all';\nlet refreshing = false;\n\nconst statusMeta = {\n  WAITING: { label: 'รอเลข', cls: 'waiting' },\n  OVERDUE: { label: 'เกิน 2 วัน', cls: 'overdue' },\n  RECEIVED: { label: 'ได้เลขแล้ว', cls: 'received' },\n  UNMATCHED: { label: 'จับคู่ไม่ได้', cls: 'unmatched' }\n};\n\nfunction fmt(value) {\n  if (!value) return '—';\n  const d = new Date(value);\n  if (!Number.isFinite(d.getTime())) return '—';\n  return new Intl.DateTimeFormat('th-TH', {\n    day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit',\n    hour12: false, timeZone: 'Asia/Bangkok'\n  }).format(d);\n}\n\nfunction age(value) {\n  if (!value) return '';\n  const ms = Date.now() - new Date(value).getTime();\n  if (!Number.isFinite(ms) || ms < 0) return '';\n  const min = Math.floor(ms / 60000);\n  if (min < 60) return `${min} นาที`;\n  const hr = Math.floor(min / 60);\n  if (hr < 24) return `${hr} ชม.`;\n  return `${Math.floor(hr / 24)} วัน`;\n}\n\nfunction escapeHtml(value) {\n  return String(value ?? '').replace(/[&<>\"']/g, ch => ({\n    '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;'\n  }[ch]));\n}\n\nfunction shortId(id) {\n  const value = String(id || '');\n  return value.length > 9 ? value.slice(-9).toUpperCase() : value.toUpperCase();\n}\n\nfunction renderAgent() {\n  const a = snapshot.agent || {};\n  els.agent.classList.remove('online', 'offline', 'partial');\n\n  if (a.online && a.lineConnected) {\n    els.agent.classList.add('online');\n    els.agent.querySelector('span').textContent = 'AGENT + LINE ONLINE';\n  } else if (a.online) {\n    els.agent.classList.add('partial');\n    els.agent.querySelector('span').textContent = 'AGENT ONLINE · LINE OFF';\n  } else {\n    els.agent.classList.add('offline');\n    els.agent.querySelector('span').textContent = 'AGENT OFFLINE';\n  }\n\n  els.lineConnection.textContent = a.lastSeenAt\n    ? `Agent ${a.lineConnected ? 'เชื่อม LINE แล้ว' : 'ยังไม่พบ LINE'} · ${fmt(a.lastSeenAt)}`\n    : 'ยังไม่เคยได้รับ Heartbeat จาก Agent';\n}\n\nfunction renderCounts() {\n  const c = snapshot.counts || {};\n  els.waiting.textContent = c.waiting || 0;\n  els.overdue.textContent = c.overdue || 0;\n  els.received.textContent = c.receivedToday || 0;\n  els.unmatched.textContent = c.unmatched || 0;\n}\n\nfunction visibleItems() {\n  const q = String(els.search.value || '').trim().toUpperCase();\n  return (snapshot.items || []).filter(item => {\n    if (activeFilter !== 'all' && item.status.toLowerCase() !== activeFilter) return false;\n    if (q && !String(item.tracking || '').toUpperCase().includes(q) && !String(item.id || '').toUpperCase().includes(q)) return false;\n    return true;\n  });\n}\n\nfunction renderList() {\n  const items = visibleItems();\n  if (!items.length) {\n    els.list.innerHTML = '<div class=\"line-empty\">ไม่มีรายการตามตัวกรองนี้</div>';\n    return;\n  }\n\n  els.list.innerHTML = items.map(item => {\n    const meta = statusMeta[item.status] || statusMeta.WAITING;\n    const hasTracking = !!item.tracking;\n    const main = hasTracking\n      ? escapeHtml(item.tracking)\n      : `งาน #${escapeHtml(shortId(item.id))}`;\n\n    const timeText = item.status === 'RECEIVED' || item.status === 'UNMATCHED'\n      ? `รับเลข ${fmt(item.receivedAt)}`\n      : `ขอเลข ${fmt(item.requestedAt)} · รอ ${age(item.requestedAt)}`;\n\n    const recovered = item.recovered ? '<b>Reply เก่าที่ Agent กู้ได้</b>' : '';\n\n    return `\n      <article class=\"tracking-row ${meta.cls}\">\n        <div class=\"tracking-state\"><i></i><span>${meta.label}</span></div>\n        <div class=\"tracking-main\">\n          <div class=\"tracking-number ${hasTracking ? '' : 'muted'}\">${main}</div>\n          <div class=\"tracking-sub\"><span>${escapeHtml(timeText)}</span>${recovered}</div>\n        </div>\n        <button class=\"copy-track\" data-copy=\"${escapeHtml(item.tracking || '')}\" ${hasTracking ? '' : 'disabled'}>${hasTracking ? 'คัดลอก' : 'รอเลข'}</button>\n      </article>`;\n  }).join('');\n}\n\nfunction render() {\n  renderAgent();\n  renderCounts();\n  renderList();\n}\n\nasync function refresh() {\n  if (refreshing) return;\n  refreshing = true;\n  try {\n    const r = await fetch('/api/line-tracking?limit=600', {\n      cache: 'no-store',\n      credentials: 'same-origin',\n      headers: { accept: 'application/json' }\n    });\n\n    if (r.status === 401) {\n      location.href = '/login';\n      return;\n    }\n\n    const data = await r.json().catch(() => ({}));\n    if (!r.ok || data.ok === false) throw new Error(data.detail || data.error || `HTTP ${r.status}`);\n\n    snapshot = data;\n    els.error.classList.add('hidden');\n    els.sync.textContent = `อัปเดตล่าสุด ${fmt(data.updatedAt || new Date().toISOString())} · รีเฟรชทุก 5 วินาที`;\n    render();\n  } catch (error) {\n    els.error.textContent = `โหลด LINE Tracking ไม่สำเร็จ: ${error?.message || error}`;\n    els.error.classList.remove('hidden');\n    els.sync.textContent = 'เชื่อมต่อไม่สำเร็จ';\n  } finally {\n    refreshing = false;\n  }\n}\n\nels.filterBar.addEventListener('click', event => {\n  const button = event.target.closest('button[data-filter]');\n  if (!button) return;\n  activeFilter = button.dataset.filter || 'all';\n  els.filterBar.querySelectorAll('button').forEach(x => x.classList.toggle('active', x === button));\n  renderList();\n});\n\nels.search.addEventListener('input', renderList);\n\nels.list.addEventListener('click', async event => {\n  const button = event.target.closest('button[data-copy]');\n  if (!button || !button.dataset.copy) return;\n  try {\n    await navigator.clipboard.writeText(button.dataset.copy);\n    const old = button.textContent;\n    button.textContent = 'คัดลอกแล้ว';\n    setTimeout(() => { button.textContent = old; }, 900);\n  } catch {\n    button.textContent = 'คัดลอกไม่ได้';\n  }\n});\n\nels.logout.addEventListener('click', async () => {\n  try { await fetch('/api/logout', { method: 'POST', credentials: 'same-origin' }); }\n  finally { location.href = '/login'; }\n});\n\nrefresh();\nsetInterval(refresh, 5000);\n",
  "line-agent/agent.mjs": "import fs from 'node:fs';\nimport path from 'node:path';\nimport os from 'node:os';\nimport crypto from 'node:crypto';\nimport CDP from 'chrome-remote-interface';\n\nconst VERSION = '1.0.0';\nconst LINE_EXTENSION_ID = 'ophjlpahpchlmihnnnihgmmeilfjmjjc';\nconst LINE_URL_PREFIX = `chrome-extension://${LINE_EXTENSION_ID}/`;\nconst LOCAL_APPDATA = process.env.LOCALAPPDATA || path.join(os.homedir(), 'AppData', 'Local');\nconst ROOT = path.join(LOCAL_APPDATA, 'LineTrackingAgent');\nconst CONFIG_PATH = path.join(ROOT, 'config.json');\nconst STATE_PATH = path.join(ROOT, 'state.json');\nconst LOG_PREFIX = '[LINE-AGENT]';\nconst DAY = 24 * 60 * 60 * 1000;\n\nfs.mkdirSync(ROOT, { recursive: true });\n\nfunction log(...args) {\n  console.log(new Date().toISOString(), LOG_PREFIX, ...args);\n}\n\nfunction sha(value) {\n  return crypto.createHash('sha256').update(String(value || ''), 'utf8').digest('hex');\n}\n\nfunction readJson(file, fallback) {\n  try { return JSON.parse(fs.readFileSync(file, 'utf8')); }\n  catch { return structuredClone(fallback); }\n}\n\nfunction atomicWrite(file, data) {\n  const tmp = `${file}.tmp`;\n  fs.writeFileSync(tmp, JSON.stringify(data, null, 2), 'utf8');\n  try {\n    fs.renameSync(tmp, file);\n  } catch {\n    fs.copyFileSync(tmp, file);\n    fs.rmSync(tmp, { force: true });\n  }\n}\n\nfunction loadConfig() {\n  const cfg = readJson(CONFIG_PATH, {});\n  const serverUrl = String(process.env.LINE_TRACK_SERVER_URL || cfg.serverUrl || '').trim().replace(/\\/+$/, '');\n  const secret = String(process.env.LINE_AGENT_SECRET || cfg.secret || '').trim();\n  const debugPort = Number(process.env.LINE_DEBUG_PORT || cfg.debugPort || 9222);\n  const roomName = String(process.env.LINE_ROOM_NAME || cfg.roomName || 'ติดตามของ ขอเลขพัสดุ').trim();\n\n  if (!/^https?:\\/\\//i.test(serverUrl)) {\n    throw new Error(`ตั้งค่า serverUrl ก่อน: ${CONFIG_PATH}`);\n  }\n  if (!secret) throw new Error(`ตั้งค่า secret ก่อน: ${CONFIG_PATH}`);\n\n  return { serverUrl, secret, debugPort, roomName };\n}\n\nconst config = loadConfig();\nconst agentId = `pc_${sha(`${os.hostname()}|${os.userInfo().username}`).slice(0, 16)}`;\nconst blankState = { v: 1, pending: [], received: [], queue: [] };\nconst state = readJson(STATE_PATH, blankState);\nif (!Array.isArray(state.pending)) state.pending = [];\nif (!Array.isArray(state.received)) state.received = [];\nif (!Array.isArray(state.queue)) state.queue = [];\n\nfunction saveState() {\n  const now = Date.now();\n  state.pending = state.pending\n    .filter(x => now - Date.parse(x.requestedAt || 0) < 60 * DAY)\n    .slice(-6000);\n  state.received = state.received\n    .filter(x => now - Date.parse(x.receivedAt || 0) < 60 * DAY)\n    .slice(-6000);\n  state.queue = state.queue.slice(-10000);\n  atomicWrite(STATE_PATH, state);\n}\n\nfunction eventId(type, material = '') {\n  return `${type}_${Date.now().toString(36)}_${sha(`${material}|${crypto.randomUUID()}`).slice(0, 14)}`;\n}\n\nfunction enqueue(event, { heartbeat = false } = {}) {\n  if (heartbeat) state.queue = state.queue.filter(x => x.type !== 'heartbeat');\n  state.queue.push(event);\n  saveState();\n}\n\nlet flushing = false;\nlet lastPostError = '';\n\nasync function flushQueue() {\n  if (flushing || !state.queue.length) return;\n  flushing = true;\n\n  try {\n    while (state.queue.length) {\n      const batch = state.queue.slice(0, 25);\n      const r = await fetch(`${config.serverUrl}/api/line-tracking`, {\n        method: 'POST',\n        headers: {\n          authorization: `Bearer ${config.secret}`,\n          'content-type': 'application/json',\n          accept: 'application/json'\n        },\n        body: JSON.stringify({ events: batch }),\n        signal: AbortSignal.timeout(12000)\n      });\n\n      const data = await r.json().catch(() => ({}));\n      if (!r.ok || data.ok === false) {\n        throw new Error(data.detail || data.error || `HTTP ${r.status}`);\n      }\n\n      state.queue.splice(0, batch.length);\n      saveState();\n      lastPostError = '';\n    }\n  } catch (error) {\n    const message = String(error?.message || error || '');\n    if (message !== lastPostError) {\n      lastPostError = message;\n      log('Sync pending:', message);\n    }\n  } finally {\n    flushing = false;\n  }\n}\n\nsetInterval(flushQueue, 3000);\n\nfunction keyHashes(keys) {\n  return [...new Set((Array.isArray(keys) ? keys : [])\n    .map(x => String(x || '').trim())\n    .filter(Boolean)\n    .map(sha))];\n}\n\nfunction sharesKey(a, b) {\n  const set = new Set(a || []);\n  return (b || []).some(x => set.has(x));\n}\n\nfunction requestFromPage(message) {\n  const hashes = keyHashes(message.matchKeys);\n  if (!hashes.length) return;\n\n  const existing = state.pending.find(x => !x.receivedAt && sharesKey(x.keyHashes, hashes));\n  if (existing) return;\n\n  const requestedAt = new Date().toISOString();\n  const requestId = `req_${Date.now().toString(36)}_${crypto.randomUUID().replace(/-/g, '').slice(0, 10)}`;\n  state.pending.push({ requestId, keyHashes: hashes, requestedAt, receivedAt: null, tracking: null });\n\n  enqueue({\n    type: 'request',\n    eventId: eventId('request', requestId),\n    requestId,\n    occurredAt: requestedAt,\n    agentId\n  });\n\n  log('REQUEST', requestId, 'waiting=', state.pending.filter(x => !x.receivedAt).length);\n}\n\nfunction trackingFromPage(message) {\n  const tracking = String(message.tracking || '').toUpperCase();\n  if (!/^TH[A-Z0-9]{8,20}$/.test(tracking)) return;\n  if (state.received.some(x => x.tracking === tracking)) return;\n\n  const hashes = keyHashes(message.matchKeys);\n  const candidates = state.pending\n    .filter(x => !x.receivedAt && sharesKey(x.keyHashes, hashes))\n    .sort((a, b) => Date.parse(b.requestedAt) - Date.parse(a.requestedAt));\n\n  const found = candidates[0] || null;\n  const receivedAt = new Date().toISOString();\n  let requestId = '';\n  let recovered = false;\n\n  if (found) {\n    requestId = found.requestId;\n    found.receivedAt = receivedAt;\n    found.tracking = tracking;\n  } else if (hashes.length && message.replyOriginal === true) {\n    requestId = `rec_${Date.now().toString(36)}_${sha(tracking).slice(0, 8)}`;\n    recovered = true;\n  }\n\n  state.received.push({ tracking, receivedAt, requestId, recovered });\n\n  enqueue({\n    type: 'tracking',\n    eventId: eventId('tracking', tracking),\n    requestId,\n    tracking,\n    occurredAt: receivedAt,\n    recovered,\n    agentId\n  });\n\n  log('TRACKING', tracking, found ? 'MATCHED' : recovered ? 'RECOVERED_REPLY' : 'UNMATCHED');\n}\n\nfunction handlePageMessage(raw) {\n  let message;\n  try { message = JSON.parse(raw); }\n  catch { return; }\n\n  if (message?.type === 'ready') {\n    log(`DOM monitor ready · baseline ${message.baseline || 0} bubble(s)`);\n    return;\n  }\n\n  if (message?.type === 'request') requestFromPage(message);\n  if (message?.type === 'tracking') trackingFromPage(message);\n}\n\nfunction injectedScript(roomName) {\n  const roomLiteral = JSON.stringify(roomName);\n  return `(() => {\n    try { window.__LINE_TRACKER_AGENT_V1__?.observer?.disconnect?.(); } catch {}\n\n    const SELECTOR = 'div[class*=\"messageLayout-module__content\"]';\n    const TRACK_RE = /\\\\\\\\bTH[A-Z0-9]{8,20}\\\\\\\\b/gi;\n    const lastSignature = new WeakMap();\n\n    function clean(value = '') {\n      return String(value)\n        .replace(/[\\\\\\\\u200B-\\\\\\\\u200D\\\\\\\\u2060\\\\\\\\uFEFF]/g, '')\n        .replace(/อ่านแล้ว\\\\\\\\s*\\\\\\\\d*/g, '')\n        .replace(/\\\\\\\\b\\\\\\\\d{1,2}[.:]\\\\\\\\d{2}\\\\\\\\s*น\\\\\\\\.?/g, '')\n        .replace(/\\\\\\\\r/g, '')\n        .replace(/[ \\\\\\\\t]+/g, ' ')\n        .replace(/\\\\\\\\n{3,}/g, '\\\\\\\\n\\\\\\\\n')\n        .trim();\n    }\n\n    function fnv(value) {\n      let h = 2166136261;\n      for (let i = 0; i < value.length; i++) {\n        h ^= value.charCodeAt(i);\n        h = Math.imul(h, 16777619);\n      }\n      return (h >>> 0).toString(36);\n    }\n\n    function trackingNumbers(text) {\n      TRACK_RE.lastIndex = 0;\n      const out = text.toUpperCase().match(TRACK_RE) || [];\n      TRACK_RE.lastIndex = 0;\n      return [...new Set(out)];\n    }\n\n    function looksLikeOrder(text) {\n      let score = 0;\n      if (/0\\\\\\\\d{8,9}/.test(text)) score++;\n      if (/COD\\\\\\\\s*[\\\\\\\\d,.]+/i.test(text)) score++;\n      if (/ที่อยู่/i.test(text)) score++;\n      if (/\\\\\\\\bFB\\\\\\\\.?/i.test(text)) score++;\n      if (/\\\\\\\\bP\\\\\\\\.?/i.test(text)) score++;\n      if (/โปร\\\\\\\\s*\\\\\\\\d+/i.test(text)) score++;\n      return score >= 2 && text.length >= 35;\n    }\n\n    function normalizeOrder(text) {\n      let t = clean(text);\n      const marker = t.search(/\\\\\\\\.[A-Za-z]=/);\n      if (marker > 0) t = t.slice(marker);\n      return t;\n    }\n\n    function deriveMatchKeys(text) {\n      const normalized = normalizeOrder(text);\n      const phone = normalized.match(/(?:^|[^\\\\\\\\d])(0\\\\\\\\d{8,9})(?!\\\\\\\\d)/)?.[1] || '';\n      const cod = normalized.match(/COD\\\\\\\\s*([\\\\\\\\d,.]+)/i)?.[1]?.replace(/,/g, '') || '';\n      const codes = (normalized.toUpperCase().match(/\\\\\\\\b[A-Z]{1,6}\\\\\\\\d{1,6}\\\\\\\\b/g) || [])\n        .filter(x => !x.startsWith('TH'))\n        .slice(0, 3);\n\n      const keys = [];\n      if (normalized) keys.push('exact|' + normalized.slice(0, 1200));\n      if (phone) keys.push(['fields', phone, codes[0] || '', cod].join('|'));\n      return keys;\n    }\n\n    function emit(payload) {\n      try { window.lineTrackerEmit(JSON.stringify(payload)); } catch {}\n    }\n\n    function processBubble(el) {\n      if (!(el instanceof Element)) return;\n      const raw = clean(el.innerText || '');\n      if (!raw) return;\n\n      const signature = fnv(raw);\n      if (lastSignature.get(el) === signature) return;\n      lastSignature.set(el, signature);\n\n      const tracking = trackingNumbers(raw);\n\n      if (!tracking.length) {\n        if (!looksLikeOrder(raw)) return;\n        emit({ type: 'request', matchKeys: deriveMatchKeys(raw), fingerprint: signature });\n        return;\n      }\n\n      let original = raw;\n      for (const number of tracking) original = original.replaceAll(number, '');\n      original = clean(original);\n\n      const hasOriginal = looksLikeOrder(original);\n      const keys = hasOriginal ? deriveMatchKeys(original) : [];\n\n      for (const number of tracking) {\n        emit({\n          type: 'tracking',\n          tracking: number,\n          matchKeys: keys,\n          replyOriginal: hasOriginal\n        });\n      }\n    }\n\n    function collect(node) {\n      const set = new Set();\n      if (!(node instanceof Element)) return set;\n      if (node.matches?.(SELECTOR)) set.add(node);\n      const parent = node.closest?.(SELECTOR);\n      if (parent) set.add(parent);\n      node.querySelectorAll?.(SELECTOR).forEach(x => set.add(x));\n      return set;\n    }\n\n    const existing = [...document.querySelectorAll(SELECTOR)];\n    for (const el of existing) {\n      const t = clean(el.innerText || '');\n      if (t) lastSignature.set(el, fnv(t));\n    }\n\n    const observer = new MutationObserver(mutations => {\n      const queue = new Set();\n      for (const mutation of mutations) {\n        if (mutation.target instanceof Element) {\n          const parent = mutation.target.closest?.(SELECTOR);\n          if (parent) queue.add(parent);\n        }\n        for (const node of mutation.addedNodes) {\n          for (const bubble of collect(node)) queue.add(bubble);\n        }\n      }\n      if (queue.size) setTimeout(() => queue.forEach(processBubble), 220);\n    });\n\n    observer.observe(document.body, {\n      subtree: true,\n      childList: true,\n      characterData: true\n    });\n\n    window.__LINE_TRACKER_AGENT_V1__ = {\n      alive: true,\n      observer,\n      roomName: ${roomLiteral},\n      startedAt: Date.now()\n    };\n\n    emit({ type: 'ready', baseline: existing.length });\n    return true;\n  })()`;\n}\n\nlet lineConnected = false;\n\nfunction heartbeat() {\n  enqueue({\n    type: 'heartbeat',\n    eventId: eventId('heartbeat', String(lineConnected)),\n    occurredAt: new Date().toISOString(),\n    agentId,\n    agentVersion: VERSION,\n    lineConnected\n  }, { heartbeat: true });\n}\nsetInterval(heartbeat, 30000);\nheartbeat();\n\nasync function findTarget() {\n  const targets = await CDP.List({ host: '127.0.0.1', port: config.debugPort });\n  return targets.find(x => String(x.url || '').startsWith(LINE_URL_PREFIX)) || null;\n}\n\nasync function runSession() {\n  const target = await findTarget();\n  if (!target) throw new Error('ยังไม่พบ LINE Chrome Extension ใน Chrome profile ของ Agent');\n\n  const client = await CDP({\n    target,\n    host: '127.0.0.1',\n    port: config.debugPort\n  });\n\n  const { Runtime, Page } = client;\n  await Runtime.enable();\n  await Page.enable();\n  await Runtime.addBinding({ name: 'lineTrackerEmit' });\n\n  Runtime.bindingCalled(event => {\n    if (event.name === 'lineTrackerEmit') handlePageMessage(event.payload);\n  });\n\n  let injecting = false;\n  const inject = async () => {\n    if (injecting) return;\n    injecting = true;\n    try {\n      await Runtime.evaluate({\n        expression: injectedScript(config.roomName),\n        awaitPromise: false,\n        returnByValue: true\n      });\n      lineConnected = true;\n      heartbeat();\n    } finally {\n      injecting = false;\n    }\n  };\n\n  await inject();\n  Page.loadEventFired(() => setTimeout(() => inject().catch(error => log('Reinject failed:', error?.message || error)), 600));\n\n  const watchdog = setInterval(async () => {\n    try {\n      const result = await Runtime.evaluate({\n        expression: 'Boolean(window.__LINE_TRACKER_AGENT_V1__?.alive)',\n        returnByValue: true\n      });\n      if (!result?.result?.value) await inject();\n    } catch {\n      lineConnected = false;\n    }\n  }, 10000);\n\n  log('Connected to LINE Chrome Extension target');\n\n  await new Promise(resolve => client.once('disconnect', resolve));\n  clearInterval(watchdog);\n  lineConnected = false;\n  heartbeat();\n}\n\nprocess.on('SIGINT', () => {\n  saveState();\n  process.exit(0);\n});\nprocess.on('SIGTERM', () => {\n  saveState();\n  process.exit(0);\n});\n\nwhile (true) {\n  try {\n    await runSession();\n  } catch (error) {\n    lineConnected = false;\n    log(String(error?.message || error));\n  }\n\n  await flushQueue();\n  await new Promise(resolve => setTimeout(resolve, 5000));\n}\n",
  "line-agent/SETUP.bat": "@echo off\nsetlocal EnableExtensions\nchcp 65001 >nul\ntitle LINE Tracking Agent - Setup\n\nset \"ROOT=%LOCALAPPDATA%\\LineTrackingAgent\"\nset \"APP=%ROOT%\\app\"\nset \"PROFILE=%ROOT%\\ChromeProfile\"\n\necho.\necho ===============================================\necho   LINE Tracking Agent - ติดตั้งครั้งแรก\necho ===============================================\necho.\n\nwhere node >nul 2>nul || (\n  echo [ERROR] ไม่พบ Node.js 20+\n  pause\n  exit /b 1\n)\n\nfor /f \"tokens=1 delims=.\" %%V in ('node -p \"process.versions.node\"') do set \"NODE_MAJOR=%%V\"\nif %NODE_MAJOR% LSS 20 (\n  echo [ERROR] ต้องใช้ Node.js 20 ขึ้นไป\n  pause\n  exit /b 1\n)\n\nif not exist \"%ROOT%\" mkdir \"%ROOT%\"\nif not exist \"%APP%\" mkdir \"%APP%\"\n\necho [1/5] Copy agent files...\nxcopy \"%~dp0*\" \"%APP%\\\" /E /I /Y /EXCLUDE:\"%~dp0setup-exclude.txt\" >nul\n\necho [2/5] Install local dependency...\npushd \"%APP%\"\ncall npm install --omit=dev\nif errorlevel 1 (\n  popd\n  echo [ERROR] npm install ไม่สำเร็จ\n  pause\n  exit /b 1\n)\npopd\n\necho.\nset /p \"SERVER_URL=ใส่ URL เว็บ Vercel เช่น https://your-project.vercel.app : \"\nif \"%SERVER_URL%\"==\"\" (\n  echo [ERROR] ต้องใส่ URL Vercel\n  pause\n  exit /b 1\n)\n\nfor /f %%S in ('powershell -NoProfile -Command \"$b=New-Object byte[] 32; $r=[Security.Cryptography.RandomNumberGenerator]::Create(); $r.GetBytes($b); (($b|ForEach-Object {$_.ToString('x2')}) -join '')\"') do set \"AGENT_SECRET=%%S\" \n\necho [3/5] Save local config...\npowershell -NoProfile -Command \"$o=[ordered]@{serverUrl='%SERVER_URL%';secret='%AGENT_SECRET%';debugPort=9222;roomName='ติดตามของ ขอเลขพัสดุ'}; $j=$o|ConvertTo-Json; [IO.File]::WriteAllText('%ROOT%\\config.json',$j,(New-Object Text.UTF8Encoding($false)))\"\n\necho [4/5] Create auto-start task...\npowershell -NoProfile -ExecutionPolicy Bypass -Command \"$p=Join-Path $env:LOCALAPPDATA 'LineTrackingAgent\\app\\START-HIDDEN.vbs'; $a=New-ScheduledTaskAction -Execute 'wscript.exe' -Argument (([char]34)+$p+([char]34)); $t=New-ScheduledTaskTrigger -AtLogOn; Register-ScheduledTask -TaskName 'LINE Tracking Agent' -Action $a -Trigger $t -Description 'Background LINE parcel tracking agent' -Force | Out-Null\"\nif errorlevel 1 echo [WARN] สร้าง Task Scheduler ไม่สำเร็จ สามารถใช้ START.bat เองได้\n\necho [5/5] Open dedicated Chrome profile for LINE setup...\n\nset \"CHROME=%ProgramFiles%\\Google\\Chrome\\Application\\chrome.exe\"\nif not exist \"%CHROME%\" set \"CHROME=%ProgramFiles(x86)%\\Google\\Chrome\\Application\\chrome.exe\"\nif not exist \"%CHROME%\" set \"CHROME=%LOCALAPPDATA%\\Google\\Chrome\\Application\\chrome.exe\"\n\nif exist \"%CHROME%\" (\n  start \"\" \"%CHROME%\" --user-data-dir=\"%PROFILE%\" \"https://chromewebstore.google.com/detail/line/ophjlpahpchlmihnnnihgmmeilfjmjjc\"\n) else (\n  echo [WARN] หา Chrome ไม่เจอ เปิด Chrome เองแล้วใช้ profile แยกได้\n)\n\necho.\necho ==============================================================\necho   สำคัญ: ตั้งค่า Vercel Environment Variable\necho ==============================================================\necho.\necho LINE_AGENT_SECRET\necho %AGENT_SECRET%\necho.\necho ถ้าโปรเจกต์ยังไม่มี Vercel Blob ให้เชื่อม Blob Storage ก่อน\necho ถ้าเว็บเดิมใช้ PLSM_CONFIG_STORE=blob อยู่แล้ว ปกติใช้ Blob เดิมได้เลย\necho.\necho ขั้นต่อไป:\necho 1. Copy secret ด้านบนไปใส่ Vercel Project - Settings - Environment Variables\necho 2. ใน Chrome ที่เปิดขึ้นมา ติดตั้ง LINE Extension\necho 3. Login LINE ด้วย QR ตามปกติ\necho 4. เปิดกลุ่ม \"ติดตามของ ขอเลขพัสดุ\" ค้างไว้\necho 5. รัน \"%APP%\\START.bat\" หนึ่งครั้งเพื่อทดสอบ\necho.\necho หลังจากนี้ Task Scheduler จะเปิด Agent ให้อัตโนมัติตอน Login Windows\necho.\npause\n",
  "line-agent/UNINSTALL.bat": "@echo off\nsetlocal\nchcp 65001 >nul\necho Removing LINE Tracking Agent auto-start...\nschtasks /Delete /TN \"LINE Tracking Agent\" /F >nul 2>nul\necho.\necho Auto-start removed.\necho Local data is still kept at:\necho %LOCALAPPDATA%\\LineTrackingAgent\necho.\necho ถ้าต้องการลบข้อมูลด้วย ให้ปิด Agent/Chrome profile ก่อน แล้วลบโฟลเดอร์นี้เอง\npause\n",
  "line-agent/setup-exclude.txt": "node_modules\nstate.json\nconfig.json\n",
  "line-agent/README-TH.md": "# LINE Tracking Agent (Windows)\n\nตัว Agent นี้อ่าน DOM ของ **LINE Chrome Extension ทางการ** ผ่าน Chrome DevTools Protocol บน `127.0.0.1` เท่านั้น\n\nมันจะไม่:\n- ขยับเมาส์\n- พิมพ์ข้อความ\n- ส่งข้อความเข้า LINE\n- กดอ่านห้องอื่น\n- อัปโหลดชื่อ เบอร์ ที่อยู่ หรือข้อความลูกค้าไปเว็บ\n\nข้อมูลที่ส่งขึ้น Vercel มีเฉพาะ:\n- request id แบบสุ่ม/แฮช\n- เวลา\n- สถานะ\n- เลขพัสดุ `TH...`\n- heartbeat ของ Agent\n\n## ติดตั้ง\n\n1. ที่ Vercel เชื่อม Blob Storage (ถ้าเว็บเดิมใช้ Blob อยู่แล้วไม่ต้องสร้างใหม่)\n2. รัน `SETUP.bat`\n3. Copy ค่า `LINE_AGENT_SECRET` ที่ SETUP สร้าง ไปใส่ Vercel:\n   - Project → Settings → Environment Variables\n   - ชื่อ `LINE_AGENT_SECRET`\n4. Redeploy Vercel\n5. ใน Chrome profile ที่ SETUP เปิด:\n   - ติดตั้ง LINE Chrome Extension\n   - Login ด้วย QR\n   - เปิดกลุ่ม `ติดตามของ ขอเลขพัสดุ` ค้างไว้\n6. รัน `START.bat`\n\nหน้าเว็บใหม่:\n`https://<project>.vercel.app/line-tracking`\n\n## การรอข้ามวัน\n\nงานที่ Agent เห็นตอนส่งจะถูกเก็บใน `%LOCALAPPDATA%\\LineTrackingAgent\\state.json`\nจึงรอ Reply ได้หลายวัน แม้ Agent restart ระหว่างนั้น\n\n- 0–2 วัน = WAITING\n- เกิน 2 วัน = OVERDUE\n- Reply + TH... = RECEIVED\n- TH... ที่ไม่มีข้อความต้นฉบับให้จับ = UNMATCHED\n\n## Log\n\n`%LOCALAPPDATA%\\LineTrackingAgent\\agent.log`\n\n## หมายเหตุ\n\nChrome profile ของ Agent เป็น profile แยก เพื่อไม่รบกวน Chrome ที่ใช้ทำงานประจำ\nRemote debugging bind เฉพาะ `127.0.0.1`\n",
  "line-agent/START-HIDDEN.vbs": "Set shell = CreateObject(\"WScript.Shell\")\nroot = shell.ExpandEnvironmentStrings(\"%LOCALAPPDATA%\")\nbat = root & \"\\LineTrackingAgent\\app\\START.bat\"\nshell.Run Chr(34) & bat & Chr(34), 0, False\n",
  "line-agent/START.bat": "@echo off\nsetlocal EnableExtensions\nchcp 65001 >nul\n\nset \"ROOT=%LOCALAPPDATA%\\LineTrackingAgent\"\nset \"APP=%ROOT%\\app\"\nset \"PROFILE=%ROOT%\\ChromeProfile\"\n\nset \"CHROME=%ProgramFiles%\\Google\\Chrome\\Application\\chrome.exe\"\nif not exist \"%CHROME%\" set \"CHROME=%ProgramFiles(x86)%\\Google\\Chrome\\Application\\chrome.exe\"\nif not exist \"%CHROME%\" set \"CHROME=%LOCALAPPDATA%\\Google\\Chrome\\Application\\chrome.exe\"\n\nif not exist \"%CHROME%\" (\n  echo [ERROR] Chrome not found >> \"%ROOT%\\agent.log\"\n  exit /b 1\n)\n\nif not exist \"%ROOT%\\config.json\" (\n  echo [ERROR] config.json not found. Run SETUP.bat first. >> \"%ROOT%\\agent.log\"\n  exit /b 1\n)\n\nstart \"\" /min \"%CHROME%\" ^\n  --remote-debugging-port=9222 ^\n  --remote-debugging-address=127.0.0.1 ^\n  --remote-allow-origins=* ^\n  --user-data-dir=\"%PROFILE%\" ^\n  --start-minimized ^\n  \"chrome-extension://ophjlpahpchlmihnnnihgmmeilfjmjjc/index.html\"\n\ntimeout /t 4 /nobreak >nul\n\ncd /d \"%APP%\"\nnode agent.mjs >> \"%ROOT%\\agent.log\" 2>&1\n",
  "line-agent/package.json": "{\n  \"name\": \"line-tracking-local-agent\",\n  \"version\": \"1.0.0\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"engines\": { \"node\": \">=20\" },\n  \"dependencies\": { \"chrome-remote-interface\": \"0.33.3\" }\n}\n"
};
for (const [p, content] of Object.entries(newFiles)) write(p, content);

// api/diagnostics.js
backup('api/diagnostics.js');
write('api/diagnostics.js', "import { diagnostics, facebookPages } from '../lib/handlers.mjs';\nimport { lineTrackingRoute } from '../lib/line-tracking.mjs';\nimport { readJsonBody, sendNode } from '../lib/vercel.mjs';\n\n// One Vercel Function serves:\n//   /api/diagnostics\n//   /api/facebook-pages -> rewritten here with ?mode=facebook-pages\n//   /api/line-tracking  -> rewritten here with ?mode=line-tracking\n// This keeps the Hobby deployment at 12 direct functions.\nexport default async function handler(req, res) {\n  const mode = String(req.query?.mode || '').trim().toLowerCase();\n  const headers = req.headers || {};\n\n  if (mode === 'line-tracking') {\n    const body = req.method === 'POST' ? await readJsonBody(req) : {};\n    return sendNode(res, await lineTrackingRoute({\n      method: req.method,\n      headers,\n      body,\n      query: req.query || {}\n    }));\n  }\n\n  if (req.method !== 'GET') {\n    return sendNode(res, {\n      status: 405,\n      headers: { allow: 'GET' },\n      body: 'Method Not Allowed'\n    });\n  }\n\n  if (mode === 'facebook-pages') {\n    return sendNode(res, await facebookPages({ headers }));\n  }\n\n  return sendNode(res, await diagnostics({\n    headers,\n    query: req.query || {}\n  }));\n}\n");

// server.mjs
{
  const p = 'server.mjs';
  backup(p);
  let s = read(p);
  s = replaceOnce(
    s,
    "import { diagnostics, facebookPages, getSettings, history, login, logout, orderEvents, pageHealth, reportBatch, reportPlan, sales, saveSettings, securityToken, shops } from './lib/handlers.mjs';\n",
    "import { diagnostics, facebookPages, getSettings, history, login, logout, orderEvents, pageHealth, reportBatch, reportPlan, sales, saveSettings, securityToken, shops } from './lib/handlers.mjs';\nimport { lineTrackingRoute } from './lib/line-tracking.mjs';\n",
    'server import'
  );
  s = replaceOnce(
    s,
    "  '/api/facebook-pages':facebookPages,\n",
    "  '/api/facebook-pages':facebookPages,\n  '/api/line-tracking':lineTrackingRoute,\n",
    'server api route'
  );
  s = replaceOnce(
    s,
    "  const routes={'/':'index.html','/login':'login.html','/settings':'settings.html'};\n",
    "  const routes={'/':'index.html','/login':'login.html','/settings':'settings.html','/line-tracking':'line-tracking.html'};\n",
    'server page route'
  );
  write(p, s);
}

// vercel.json
{
  const p = 'vercel.json';
  backup(p);
  const data = JSON.parse(read(p));
  data.rewrites = Array.isArray(data.rewrites) ? data.rewrites : [];
  if (!data.rewrites.some(x => x.source === '/api/line-tracking')) {
    data.rewrites.push({ source:'/api/line-tracking', destination:'/api/diagnostics?mode=line-tracking' });
  }
  write(p, JSON.stringify(data, null, 2) + '\n');
}

// public/index.html nav button
{
  const p = 'public/index.html';
  backup(p);
  let s = read(p);
  const marker = `      <a href="/settings" class="icon-btn" title="Settings" aria-label="Settings">`;
  const add = `      <a href="/line-tracking" class="icon-btn" title="LINE Tracking" aria-label="LINE Tracking">
        <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h11v9H4zM15 10h3l2 3v3h-5M7 19a2 2 0 1 0 0-4 2 2 0 0 0 0 4ZM17 19a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z"/></svg>
      </a>
`;
  if (!s.includes('href="/line-tracking"')) {
    must(s.includes(marker), 'index nav marker not found');
    s = s.replace(marker, add + marker);
  }
  write(p, s);
}

